sections.css:
h1{font-family: var(--font-hero); font-weight: 500; letter-spacing: -0.02em;}
.fullscreen-video-container{position: absolute; top: 0px; left: 0px; width: 100vw; height: 100vh; z-index: 0; overflow: hidden; border-radius: 0px;}
.fullscreen-video-container video{width: 100%; height: 100%; object-fit: cover; filter: saturate(1.2) contrast(1.1) brightness(0.85); border-radius: 0px;}
.video-vignette{position: absolute; inset: 0px; background: radial-gradient(circle at center, transparent 0%, rgba(0,0,0,0.4) 60%, var(--color-bg) 100%); border-radius: 0px; z-index: 1; pointer-events: none;}
.hero-typography{position: relative; z-index: 20; padding: 3rem; transform: translate3d(0px, 0px, 0px); will-change: transform, opacity;}
.dew-drop{display: inline-flex; align-items: center; gap: 12px; padding: 16px 36px; background: linear-gradient(135deg, rgba(255, 255, 255, 0.15) 0%, rgba(255, 255, 255, 0.05) 100%); backdrop-filter: blur(24px) saturate(1.8); border: 0.5px solid rgba(255, 255, 255, 0.4); box-shadow: rgba(255, 255, 255, 0.5) 0px 1px 2px inset, rgba(255, 255, 255, 0.1) 0px -1px 4px inset, rgba(0, 0, 0, 0.2) 0px 12px 32px; border-radius: 100px; color: white; text-decoration: none; font-weight: 500; font-size: 0.9rem; letter-spacing: 0.05em; text-transform: uppercase; transition: 0.5s cubic-bezier(0.25, 1, 0.5, 1); cursor: pointer; position: relative; overflow: hidden;}
.dew-drop::before{content: ""; position: absolute; inset: 0px; border-radius: 100px; box-shadow: rgba(255, 255, 255, 0.4) 0px 0px 20px inset; opacity: 0; transition: opacity 0.5s;}
.dew-drop:hover{transform: translateY(-4px) scale(1.02); box-shadow: rgba(255, 255, 255, 0.8) 0px 1px 2px inset, rgba(255, 255, 255, 0.2) 0px -1px 4px inset, rgba(0, 0, 0, 0.4) 0px 20px 48px; background: linear-gradient(135deg, rgba(255, 255, 255, 0.25) 0%, rgba(255, 255, 255, 0.1) 100%);}
.dew-drop:hover::before{opacity: 1;}
.hero-fade-in{animation: 1.5s cubic-bezier(0.25, 1, 0.5, 1) 0s 1 normal forwards running fadeIn; opacity: 0; transform: translateY(20px);}
h1{font-size: inherit; font-weight: inherit;}
a{color: inherit; text-decoration: inherit;}
h1, p{margin: 0px;}
video{display: block; vertical-align: middle;}
video{max-width: 100%; height: auto;}
