h2{font-family: var(--font-hero); font-weight: 500; letter-spacing: -0.02em;}
.rhizome-section{position: relative; padding: 12vh 5vw; container: rhizome / inline-size; background: var(--color-bg); border-radius: 0px; z-index: 10;}
.radial-leak{position: absolute; width: 60vw; height: 60vw; background: radial-gradient(circle, oklch(0.88 0.1 150 / 0.15) 0%, transparent 60%); border-radius: 50%; filter: blur(50px); z-index: 0; pointer-events: none;}
.bionic-bloom{animation-duration: auto; animation-timing-function: linear; animation-delay: 0s; animation-iteration-count: 1; animation-direction: normal; animation-fill-mode: both; animation-play-state: running; animation-name: bloom-scroll; animation-timeline: view(); animation-range: entry 5% cover 35%;}
.glass-card{background: linear-gradient(rgba(255, 255, 255, 0.85) 0%, rgba(255, 255, 255, 0.4) 100%); backdrop-filter: blur(40px); border: 0.5px solid rgba(255, 255, 255, 0.7); box-shadow: rgba(0, 0, 0, 0.03) 0px 24px 64px, rgba(255, 255, 255, 0.5) 0px 1px 1px inset; padding: 3.5rem; position: relative; z-index: 1; transition: transform 0.4s, box-shadow 0.4s;}
.glass-card:hover{transform: translateY(-5px); box-shadow: rgba(0, 0, 0, 0.06) 0px 32px 80px, rgba(255, 255, 255, 0.8) 0px 1px 1px inset;}
